<?php

namespace Ecole2Nat\Admin\Pages;

use Ecole2Nat\MembershipBilling\MembershipInvoiceService;

if (!defined('ABSPATH')) { exit; }

final class MembershipInvoicePage
{
    public function __construct(private ?MembershipInvoiceService $service=null){$this->service??=new MembershipInvoiceService();}

    public function render(): void
    {
        if(!current_user_can('manage_options'))wp_die(esc_html__('Accès refusé.','ecole2nat'));
        $seasons=$this->service->seasons();$seasonId=absint($_REQUEST['season_id']??0);if($seasonId<=0){foreach($seasons as $season)if((int)$season['is_current']===1){$seasonId=(int)$season['id'];break;}}
        $notice='';$error='';
        if(isset($_POST['e2n_prepare_membership_invoice'])){check_admin_referer('e2n_membership_invoices');$result=$this->service->prepare($seasonId,absint($_POST['e2n_prepare_membership_invoice']),get_current_user_id());if($result['success']){wp_safe_redirect(admin_url('admin.php?page=ecole2nat-membership-invoices&invoice_id='.(int)$result['invoice_id'].'&season_id='.$seasonId));exit;}$error=$result['message'];}
        if(isset($_POST['e2n_send_membership_invoices'])){check_admin_referer('e2n_membership_invoices');$sent=0;$failed=[];foreach((array)($_POST['swimmer_ids']??[]) as $id){$result=$this->service->send($seasonId,absint($id),get_current_user_id());if($result['success'])$sent++;else$failed[]=$result['message'];}$notice=sprintf(_n('%d facture envoyée.','%d factures envoyées.',$sent,'ecole2nat'),$sent);if($failed)$error=sprintf(__('%1$d envoi(s) ont échoué : %2$s','ecole2nat'),count($failed),implode(' — ',array_unique($failed)));}
        echo '<div class="wrap e2n-membership-invoices"><h1>'.esc_html__('Factures d’adhésion','ecole2nat').'</h1>';
        if($notice!=='')echo '<div class="notice notice-success"><p>'.esc_html($notice).'</p></div>';if($error!=='')echo '<div class="notice notice-error"><p>'.esc_html($error).'</p></div>';
        $invoiceId=absint($_GET['invoice_id']??0);if($invoiceId>0){$this->invoice($invoiceId,$seasonId);echo '</div>';return;}
        $paid=sanitize_key($_GET['paid']??'all');$sent=sanitize_key($_GET['sent']??'all');$search=sanitize_text_field(wp_unslash($_GET['s']??''));$rows=$seasonId>0?$this->service->rows($seasonId,$paid,$sent,$search):[];
        ?><p><?php esc_html_e('Les montants proviennent de la dernière synchronisation de l’onglet Inscriptions. Pass’Sport compte pour 50 € dès que la cellule est renseignée.','ecole2nat');?></p>
        <form method="get" style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:16px 0"><input type="hidden" name="page" value="ecole2nat-membership-invoices"><select name="season_id"><?php foreach($seasons as $season):?><option value="<?php echo (int)$season['id'];?>" <?php selected($seasonId,(int)$season['id']);?>><?php echo esc_html($season['name']);?></option><?php endforeach;?></select><select name="paid"><option value="all"><?php esc_html_e('Tous les paiements','ecole2nat');?></option><option value="yes" <?php selected($paid,'yes');?>><?php esc_html_e('Payé : OUI','ecole2nat');?></option><option value="no" <?php selected($paid,'no');?>><?php esc_html_e('Payé : NON / vide','ecole2nat');?></option></select><select name="sent"><option value="all"><?php esc_html_e('Toutes les factures','ecole2nat');?></option><option value="yes" <?php selected($sent,'yes');?>><?php esc_html_e('Facture envoyée : OUI','ecole2nat');?></option><option value="no" <?php selected($sent,'no');?>><?php esc_html_e('Facture envoyée : vide','ecole2nat');?></option></select><input type="search" name="s" value="<?php echo esc_attr($search);?>" placeholder="<?php esc_attr_e('Nageur ou email','ecole2nat');?>"><button class="button"><?php esc_html_e('Filtrer','ecole2nat');?></button><a class="button button-primary" href="<?php echo esc_url(admin_url('admin.php?page=ecole2nat-membership-invoices&season_id='.$seasonId.'&paid=yes&sent=no'));?>"><?php esc_html_e('À envoyer','ecole2nat');?></a></form>
        <form method="post"><?php wp_nonce_field('e2n_membership_invoices');?><input type="hidden" name="season_id" value="<?php echo (int)$seasonId;?>"><table class="widefat striped"><thead><tr><td class="check-column"><input type="checkbox" data-e2n-check-all></td><th><?php esc_html_e('Nageur','ecole2nat');?></th><th><?php esc_html_e('Total versé','ecole2nat');?></th><th><?php esc_html_e('Payé ?','ecole2nat');?></th><th><?php esc_html_e('Facture envoyée','ecole2nat');?></th><th><?php esc_html_e('Email responsable','ecole2nat');?></th><th></th></tr></thead><tbody><?php foreach($rows as $row):$effectiveSent=(int)$row['invoice_marked_sent']===1||!empty($row['sent_at']);$eligible=(int)$row['paid_flag']===1&&(float)$row['total_paid']>0&&!empty($row['responsible_email']);?><tr><th class="check-column"><input type="checkbox" name="swimmer_ids[]" value="<?php echo (int)$row['swimmer_id'];?>" <?php disabled($effectiveSent||!$eligible);?>></th><td><strong><?php echo esc_html($row['first_name'].' '.$row['last_name']);?></strong><br><small><?php echo esc_html($row['group_name']??'');?></small></td><td><?php echo esc_html(number_format((float)$row['total_paid'],2,',',' '));?> €</td><td><?php echo (int)$row['paid_flag']===1?'<span class="e2n-badge e2n-badge--success">OUI</span>':'<span class="e2n-badge">NON / vide</span>';?></td><td><?php if($effectiveSent):?><span class="e2n-badge e2n-badge--success">OUI</span><?php if(!empty($row['sent_at'])):?><br><small><?php echo esc_html(wp_date('d/m/Y H:i',strtotime($row['sent_at'])));?></small><?php else:?><br><small><?php esc_html_e('indiqué dans Excel','ecole2nat');?></small><?php endif;else:?><span class="e2n-badge">vide</span><?php endif;?></td><td><?php echo esc_html($row['responsible_email']);?></td><td><?php if(!empty($row['invoice_id'])):?><a href="<?php echo esc_url(admin_url('admin.php?page=ecole2nat-membership-invoices&season_id='.$seasonId.'&invoice_id='.(int)$row['invoice_id']));?>"><?php esc_html_e('Voir / imprimer','ecole2nat');?></a><?php elseif($eligible):?><button class="button-link" name="e2n_prepare_membership_invoice" value="<?php echo (int)$row['swimmer_id'];?>"><?php esc_html_e('Préparer','ecole2nat');?></button><?php else:?><span aria-hidden="true">—</span><?php endif;?></td></tr><?php endforeach;if($rows===[]):?><tr><td colspan="7"><?php esc_html_e('Aucun règlement ne correspond aux filtres.','ecole2nat');?></td></tr><?php endif;?></tbody></table><p><button class="button button-primary" name="e2n_send_membership_invoices" value="1" onclick="return confirm('<?php echo esc_js(__('Envoyer les factures PDF aux destinataires sélectionnés ?','ecole2nat'));?>')"><?php esc_html_e('Envoyer les factures sélectionnées','ecole2nat');?></button></p></form><script>document.querySelector('[data-e2n-check-all]')?.addEventListener('change',function(){document.querySelectorAll('input[name="swimmer_ids[]"]:not(:disabled)').forEach(e=>e.checked=this.checked)});</script></div><?php
    }

    private function invoice(int $id,int $seasonId): void
    {
        $invoice=$this->service->invoice($id);if(!$invoice){echo '<p>'.esc_html__('Facture introuvable.','ecole2nat').'</p>';return;}
        echo '<p><a href="'.esc_url(admin_url('admin.php?page=ecole2nat-membership-invoices&season_id='.$seasonId)).'">← '.esc_html__('Retour à la liste','ecole2nat').'</a> <button class="button button-primary" onclick="document.getElementById(\'e2n-invoice-preview\').contentWindow.print()">'.esc_html__('Imprimer / enregistrer en PDF','ecole2nat').'</button></p><iframe id="e2n-invoice-preview" title="'.esc_attr__('Aperçu de la facture','ecole2nat').'" srcdoc="'.esc_attr($this->service->document($invoice)).'" style="width:100%;height:1120px;background:#fff;border:1px solid #ccd0d4"></iframe>';
    }
}
